// ─── Types & helpers ─────────────────────────────────────────────────────────

interface SearchResult {
  entry: NavEntry;
  parentName: string;
  snippet: string;
  matchCount: number;
  headingSlug: string | null;
  headingText: string | null;
}

function slugify(text: string): string {
  return text
    .toLowerCase()
    .replace(/[*_`[\]()#]/g, '')
    .replace(/[^\w\s-]/g, '')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .trim();
}

const contentCache = new Map<string, string>();

async function fetchContent(file: string): Promise<string> {
  const cached = contentCache.get(file);
  if (cached !== undefined) return cached;
  try {
    const res = await fetch(`${__webpack_public_path__}content/${file}`);
    if (!res.ok) return '';
    const text = await res.text();
    contentCache.set(file, text);
    return text;
  } catch {
    contentCache.set(file, '');
    return '';
  }
}

/** Normalize text: lowercase + strip accents (á→a, ã→a, ç→c, etc.) */
function normalize(str: string): string {
  return str.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

function flattenWithParent(entries: NavEntry[], parent = ''): { entry: NavEntry; parentName: string }[] {
  return entries.flatMap((e) => {
    if (e.children) return flattenWithParent(e.children, e.name);
    if (e.file) return [{ entry: e, parentName: parent }];
    return [];
  });
}

interface SnippetResult {
  snippet: string;
  count: number;
  headingSlug: string | null;
  headingText: string | null;
}

function extractSnippet(text: string, query: string): SnippetResult {
  const normText = normalize(text);
  const q = normalize(query);
  const allLines = text.split('\n');

  let count = 0;
  let idx = 0;
  while ((idx = normText.indexOf(q, idx)) !== -1) { count++; idx += q.length; }

  // Track the nearest heading above each line
  let lastHeading: string | null = null;
  for (const line of allLines) {
    const headingMatch = line.match(/^#{1,4}\s+(.+)/);
    if (headingMatch) {
      lastHeading = headingMatch[1].trim();
    }

    if (!line.trim() || line.startsWith('```') || line.startsWith('|--')) continue;

    const clean = line.replace(/^#{1,6}\s*/, '').replace(/[*_`|]/g, '').trim();
    // Build a map from normalized index → original index
    const nfd = clean.normalize('NFD');
    const origIdx: number[] = []; // origIdx[normPos] = cleanPos
    let oi = 0;
    for (let ni = 0; ni < nfd.length; ni++) {
      const code = nfd.charCodeAt(ni);
      // Skip combining diacritical marks (U+0300–U+036F)
      if (code >= 0x0300 && code <= 0x036f) continue;
      origIdx.push(oi);
      oi++;
    }
    origIdx.push(oi); // sentinel

    const normClean = normalize(clean);
    const ci = normClean.indexOf(q);
    if (ci === -1) continue;

    // Map normalized positions back to original string positions
    const matchStart = origIdx[ci] ?? ci;
    const matchEnd = origIdx[ci + q.length] ?? (matchStart + query.length);

    const ctxStart = Math.max(0, matchStart - 50);
    const ctxEnd = Math.min(clean.length, matchEnd + 70);
    const prefix = ctxStart > 0 ? '…' : '';
    const suffix = ctxEnd < clean.length ? '…' : '';
    const before = clean.slice(ctxStart, matchStart);
    const match = clean.slice(matchStart, matchEnd);
    const after = clean.slice(matchEnd, ctxEnd);

    return {
      snippet: `${prefix}${before}<mark>${match}</mark>${after}${suffix}`,
      count,
      headingSlug: lastHeading ? slugify(lastHeading) : null,
      headingText: lastHeading,
    };
  }
  return { snippet: '', count, headingSlug: null, headingText: null };
}

// ─── Component ───────────────────────────────────────────────────────────────

interface SearchModalProps {
  open: boolean;
  onClose: () => void;
  entries: NavEntry[];
  activeId: string | null;
  onSelect: (entry: NavEntry, scrollToId?: string | null) => void;
}

export function SearchModal({ open, onClose, entries, activeId, onSelect }: SearchModalProps) {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<SearchResult[]>([]);
  const [searching, setSearching] = useState(false);
  const [selectedIdx, setSelectedIdx] = useState(0);
  const inputRef = useRef<HTMLInputElement>(null);
  const debounceRef = useRef<ReturnType<typeof setTimeout>>();

  const allLeaves = useMemo(() => flattenWithParent(entries), [entries]);

  // Focus input when opened
  useEffect(() => {
    if (open) {
      setQuery('');
      setResults([]);
      setSelectedIdx(0);
      setTimeout(() => inputRef.current?.focus(), 50);
    }
  }, [open]);

  // Close on Escape
  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') { e.preventDefault(); onClose(); }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [open, onClose]);

  const doSearch = useCallback(async (q: string) => {
    if (q.length < 2) { setResults([]); setSearching(false); return; }
    setSearching(true);

    const contents = await Promise.all(
      allLeaves.map(async ({ entry, parentName }) => {
        const text = await fetchContent(entry.file!);
        return { entry, parentName, text };
      })
    );

    const matches: SearchResult[] = [];
    for (const { entry, parentName, text } of contents) {
      const normName = normalize(entry.name);
      const normText = normalize(text);
      const ql = normalize(q);
      if (!normName.includes(ql) && !normText.includes(ql)) continue;

      const { snippet, count, headingSlug, headingText } = extractSnippet(text, q);
      const nameMatch = normName.includes(ql);
      matches.push({
        entry,
        parentName,
        snippet: snippet || (nameMatch ? entry.name : ''),
        matchCount: count + (nameMatch ? 10 : 0),
        headingSlug,
        headingText,
      });
    }

    matches.sort((a, b) => b.matchCount - a.matchCount);
    setResults(matches);
    setSelectedIdx(0);
    setSearching(false);
  }, [allLeaves]);

  useEffect(() => {
    clearTimeout(debounceRef.current);
    if (!query.trim()) { setResults([]); return; }
    debounceRef.current = setTimeout(() => doSearch(query.trim()), 250);
    return () => clearTimeout(debounceRef.current);
  }, [query, doSearch]);

  const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setSelectedIdx((i) => Math.min(i + 1, results.length - 1));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setSelectedIdx((i) => Math.max(i - 1, 0));
    } else if (e.key === 'Enter' && results[selectedIdx]) {
      e.preventDefault();
      onSelect(results[selectedIdx].entry, results[selectedIdx].headingSlug);
      onClose();
    }
  }, [results, selectedIdx, onSelect, onClose]);

  if (!open) return null;

  return (
    <Backdrop onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}>
      <Modal onKeyDown={handleKeyDown}>
        <InputRow>
          <Search size={18} color={theme.colors.accent} style={{ flexShrink: 0 }} />
          <Input
            ref={inputRef}
            placeholder="Pesquisar em todo o conteúdo…"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
          />
          <CloseBtn onClick={onClose} title="Fechar (Esc)">
            <X size={14} />
          </CloseBtn>
        </InputRow>

        <ResultsArea>
          {searching && (
            <StatusRow>
              <Spin><Loader2 size={14} /></Spin>
              A pesquisar {allLeaves.length} ficheiros…
            </StatusRow>
          )}

          {!searching && query.length >= 2 && results.length > 0 && (
            <StatusRow>
              <FileText size={13} />
              {results.length} {results.length === 1 ? 'resultado' : 'resultados'} encontrados
            </StatusRow>
          )}

          {!searching && query.length >= 2 && results.length === 0 && (
            <EmptyState>
              <Search size={32} strokeWidth={1.2} />
              Nenhum resultado para "<strong>{query}</strong>"
            </EmptyState>
          )}

          {!searching && query.length < 2 && (
            <EmptyState>
              <Search size={32} strokeWidth={1.2} />
              Escreve pelo menos 2 caracteres para pesquisar
            </EmptyState>
          )}

          {results.map((r, i) => (
            <ResultItem
              key={r.entry.id}
              selected={i === selectedIdx}
              onClick={() => { onSelect(r.entry, r.headingSlug); onClose(); }}
              onMouseEnter={() => setSelectedIdx(i)}
            >
              <ResultIcon selected={i === selectedIdx}>
                <FileText size={15} />
              </ResultIcon>
              <ResultBody>
                <ResultTitle>
                  {r.entry.name}
                  {r.matchCount > 0 && <MatchBadge>{r.matchCount > 10 ? r.matchCount - 10 : r.matchCount}</MatchBadge>}
                </ResultTitle>
                {(r.parentName || r.headingText) && (
                  <ResultParent>
                    {r.parentName}{r.parentName && r.headingText ? ' › ' : ''}{r.headingText}
                  </ResultParent>
                )}
                {r.snippet && <Snippet dangerouslySetInnerHTML={{ __html: r.snippet }} />}
              </ResultBody>
              <GoIcon selected={i === selectedIdx}>
                <ArrowRight size={14} />
              </GoIcon>
            </ResultItem>
          ))}
        </ResultsArea>

        <Footer>
          <span><Kbd>↑</Kbd> <Kbd>↓</Kbd> navegar</span>
          <span><Kbd>↵</Kbd> abrir</span>
          <span><Kbd>esc</Kbd> fechar</span>
        </Footer>
      </Modal>
    </Backdrop>
  );
}

export default SearchModal;
